Page(name: "Password reset", route: Route(path: "/reset-password"))

Build(
  Scaffold(
    appBar: SweetScoopHeader(),
    body: ScrollView(label: "Password reset", child: Column(gap: Space.md, padding: Insets(y: 12), children: [Column(gap: Space.md, padding: Insets(x: 16, y: 8), children: [
    Box(shape: BoxShape.circle, width: 64, height: 64, alignment: Anchor.center, background: Color.surfaceAlt, child: Icon(name: Icons.settings, color: Color.primary)), Text(child: "A new password", size: FontSize.xxl, weight: FontWeight.bold, fontStyle: FontStyle.italic, lineHeight: 1.15), Text(child: "We'll email you a link to choose one.", size: FontSize.sm, color: Color.textMuted), Box(padding: Space.lg, radius: Radius.xl, background: Color.surfaceAlt, child: Column(gap: Space.sm, children: [Form(id: "resetPassword", onSubmit: ResetPreviewPassword(), child: Column(gap: Space.md, children: [TextField(name: "email", label: "Your email", type: InputType.email, required: true, background: Color.surface, border: Border(width: 1, color: Color.border), radius: Radius.full), SubmitButton(label: "Email me a link", fullWidth: true)]))])), Button(label: "Back to the menu", style: ButtonStyle.ghost, icon: Icons.chevronLeft, onTap: Navigate(to: Route.menu))
  ])])),
  )
)
